import { Suspense, cache } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

// Share one request between the independently streaming dashboard sections.
const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard')
  if (!res.ok) throw new Error('Failed to load dashboard data')
  return res.json()
})

async function DashboardCards() {
  const { totalRevenue, totalInvoices } = await getDashboardData()
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

async function DashboardRevenue() {
  const { revenue } = await getDashboardData()
  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices() {
  const { invoices } = await getDashboardData()
  return <LatestInvoices invoices={invoices} />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense
        fallback={
          <div className="grid grid-cols-2 gap-4" aria-busy="true">
            <div className="card">
              <h2>Total Revenue</h2>
              <p>Loading...</p>
            </div>
            <div className="card">
              <h2>Total Invoices</h2>
              <p>Loading...</p>
            </div>
          </div>
        }
      >
        <DashboardCards />
      </Suspense>
      <Suspense
        fallback={
          <div className="chart" aria-busy="true">
            <h2>Revenue</h2>
            <p>Loading revenue...</p>
          </div>
        }
      >
        <DashboardRevenue />
      </Suspense>
      <Suspense
        fallback={
          <div className="invoices" aria-busy="true">
            <h2>Latest Invoices</h2>
            <p>Loading invoices...</p>
          </div>
        }
      >
        <DashboardInvoices />
      </Suspense>
    </main>
  )
}

